import java.util.Locale

/**
 * 월별 운행기록부 CSV. Excel에서 한글이 깨지지 않도록 UTF-8 BOM을 붙이고 줄바꿈은 CRLF로 쓴다.
 * 열은 국세청 업무용승용차 운행기록부 서식 순서를 따른다 (서식 최신 여부는 사용자가 따로 확인).
 */
object LogbookCsv {

    const val BOM = "﻿"

