package com.altrostudio.drivelog.domain.logbook

import com.altrostudio.drivelog.data.trip.TripEntity
import com.altrostudio.drivelog.data.trip.TripPurpose
import com.altrostudio.drivelog.data.trip.distanceKm
import java.time.Instant
import java.time.LocalDate
import java.time.YearMonth
import java.time.ZoneId

/** 국세청 업무용승용차 운행기록부의 한 줄 */
data class LogbookRow(
    val tripId: String,
    val date: LocalDate,
    val driver: String,
    val startOdometerKm: Double?,
    val endOdometerKm: Double?,
    val distanceKm: Double,
    /** 업무용 사용거리 중 출퇴근용 */
    val commuteKm: Double,
    /** 업무용 사용거리 중 일반 업무용 */
    val businessKm: Double,
    /** 비고(방문처) */
    val note: String?,
    val purpose: TripPurpose
)

data class LogbookSummary(
    val totalKm: Double,
    val commuteKm: Double,
    val businessKm: Double,
    val tripCount: Int,
    val unclassifiedCount: Int
) {
    /** 업무용 사용거리 = 출퇴근용 + 일반 업무용 */
    val workKm: Double get() = commuteKm + businessKm

    /** 업무사용비율(%) = 업무용 사용거리 ÷ 총 주행거리. 미분류 운행은 업무용에 넣지 않는다 */
    val workRatioPercent: Double? get() = if (totalKm > 0) workKm / totalKm * 100 else null
}

data class Logbook(val month: YearMonth, val rows: List<LogbookRow>, val summary: LogbookSummary)

/** 완료된 운행을 월별 운행기록부로 바꾼다 */
object LogbookBuilder {

    /** 그 달에 시작한 운행을 고르는 범위 [from, to) (epoch 밀리초) */
    fun monthRange(month: YearMonth, zone: ZoneId): Pair<Long, Long> =
        month.atDay(1).atStartOfDay(zone).toInstant().toEpochMilli() to
            month.plusMonths(1).atDay(1).atStartOfDay(zone).toInstant().toEpochMilli()

    fun build(month: YearMonth, trips: List<TripEntity>, zone: ZoneId, driverName: String): Logbook {
        val rows = trips.sortedBy { it.startedAt }.map { trip ->
            val distance = trip.distanceKm() ?: 0.0
            LogbookRow(
                tripId = trip.id,
                date = Instant.ofEpochMilli(trip.startedAt).atZone(zone).toLocalDate(),
                driver = driverName,
                startOdometerKm = trip.startOdometerKm,
                endOdometerKm = trip.endOdometerKm,
                distanceKm = distance,
                commuteKm = if (trip.purpose == TripPurpose.COMMUTE) distance else 0.0,
                businessKm = if (trip.purpose == TripPurpose.BUSINESS) distance else 0.0,
                note = trip.visitNote,
                purpose = trip.purpose
            )
        }
        val summary = LogbookSummary(
            totalKm = rows.sumOf { it.distanceKm },
            commuteKm = rows.sumOf { it.commuteKm },
            businessKm = rows.sumOf { it.businessKm },
            tripCount = rows.size,
            unclassifiedCount = rows.count { it.purpose == TripPurpose.UNCLASSIFIED }
        )
        return Logbook(month, rows, summary)
    }
}

package com.altrostudio.drivelog.domain.logbook

import com.altrostudio.drivelog.data.trip.TripPurpose
import java.time.format.TextStyle
import java.util.Locale

/**
 * 월별 운행기록부 CSV. Excel에서 한글이 깨지지 않도록 UTF-8 BOM을 붙이고 줄바꿈은 CRLF로 쓴다.
 * 열은 국세청 업무용승용차 운행기록부 서식 순서를 따른다 (서식 최신 여부는 사용자가 따로 확인).
 */
object LogbookCsv {

    const val BOM = "\uFEFF"

    private val HEADER = listOf(
        "사용일자", "사용자", "주행 전 계기판 거리(km)", "주행 후 계기판 거리(km)", "주행거리(km)",
        "업무용 사용거리 출퇴근용(km)", "업무용 사용거리 일반업무용(km)", "비고(방문처)", "구분"
    )

    private val PURPOSE_LABELS = mapOf(
        TripPurpose.UNCLASSIFIED to "미분류",
        TripPurpose.COMMUTE to "출퇴근",
        TripPurpose.BUSINESS to "일반업무",
        TripPurpose.PERSONAL to "비업무"
    )

    fun fileName(logbook: Logbook): String = "DriveLog_${logbook.month}.csv"

    fun build(logbook: Logbook): String {
        val rows = logbook.rows.map { row ->
            listOf(
                "${row.date}(${row.date.dayOfWeek.getDisplayName(TextStyle.SHORT, Locale.KOREAN)})",
                row.driver,
                km(row.startOdometerKm),
                km(row.endOdometerKm),
                km(row.distanceKm),
                km(row.commuteKm),
                km(row.businessKm),
                row.note.orEmpty(),
                PURPOSE_LABELS.getValue(row.purpose)
            )
        }
        val summary = logbook.summary
        val footer = listOf(
            emptyList(),
            listOf("총 주행거리(km)", km(summary.totalKm)),
            listOf("업무용 사용거리(km)", km(summary.workKm)),
            listOf("업무사용비율(%)", summary.workRatioPercent?.let { String.format(Locale.ROOT, "%.1f", it) }.orEmpty()),
            listOf("미분류 운행(건)", summary.unclassifiedCount.toString())
        )
        return BOM + (listOf(HEADER) + rows + footer).joinToString("\r\n", postfix = "\r\n") { line ->
            line.joinToString(",") { escape(it) }
        }
    }

    private fun km(value: Double?): String = value?.let { String.format(Locale.ROOT, "%.1f", it) }.orEmpty()

    /** 쉼표·따옴표·줄바꿈은 따옴표로 감싸고, =·+·-·@로 시작하는 글자는 Excel 수식으로 실행되지 않게 막는다 */
    private fun escape(value: String): String {
        val safe = if (value.firstOrNull() in FORMULA_PREFIXES && value.toDoubleOrNull() == null) "'$value" else value
        return if (safe.any { it == ',' || it == '"' || it == '\n' || it == '\r' }) {
            "\"" + safe.replace("\"", "\"\"") + "\""
        } else {
            safe
        }
    }

    private val FORMULA_PREFIXES = setOf('=', '+', '-', '@')
}

