// backend/.env 를 읽는다. 값은 화면에 출력하지 않는다
import { existsSync, readFileSync } from 'node:fs';

const ENV_FILE = new URL('../.env', import.meta.url);

export function loadEnv(required) {
  if (!existsSync(ENV_FILE)) {
    throw new Error('backend/.env 가 없습니다. backend/.env.example 을 복사해서 채워 주세요.');
  }
  const env = {};
  for (const line of readFileSync(ENV_FILE, 'utf8').split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#') || !trimmed.includes('=')) continue;
    const index = trimmed.indexOf('=');
    env[trimmed.slice(0, index).trim()] = trimmed.slice(index + 1).trim();
  }
  const missing = required.filter((key) => !env[key]);
  if (missing.length > 0) {
    throw new Error(`backend/.env 에 값이 비어 있습니다: ${missing.join(', ')}`);
  }
  return env;
}

export function projectRef(supabaseUrl) {
  return new URL(supabaseUrl).hostname.split('.')[0];
}

// Supabase 프로젝트 준비: 마이그레이션 SQL 적용 + 익명 로그인(차량 계정용) 켜기.
// Supabase Management API를 쓰므로 backend/.env 의 SUPABASE_ACCESS_TOKEN 이 필요하다.
// 사용: node backend/scripts/setup.mjs
import { readdirSync, readFileSync } from 'node:fs';
import { loadEnv, projectRef } from './env.mjs';

const env = loadEnv(['SUPABASE_URL', 'SUPABASE_ACCESS_TOKEN']);
const ref = projectRef(env.SUPABASE_URL);
const MIGRATIONS_DIR = new URL('../supabase/migrations/', import.meta.url);

async function management(path, { method = 'GET', body } = {}) {
  const response = await fetch(`https://api.supabase.com/v1/projects/${ref}${path}`, {
    method,
    headers: { Authorization: `Bearer ${env.SUPABASE_ACCESS_TOKEN}`, 'Content-Type': 'application/json' },
    body: body && JSON.stringify(body),
  });
  const text = await response.text();
  if (!response.ok) throw new Error(`${method} ${path} → ${response.status} ${text}`);
  return text ? JSON.parse(text) : null;
}

const query = (sql) => management('/database/query', { method: 'POST', body: { query: sql } });

// 1. 마이그레이션: 적용한 파일 이름을 기록해 두고 새 파일만 적용한다
await query('create table if not exists public.drivelog_migrations (name text primary key, applied_at timestamptz not null default now())');
await query('alter table public.drivelog_migrations enable row level security');
const applied = new Set((await query('select name from public.drivelog_migrations')).map((row) => row.name));
const files = readdirSync(MIGRATIONS_DIR).filter((name) => name.endsWith('.sql')).sort();
for (const name of files) {
  if (applied.has(name)) {
    console.log(`건너뜀 (이미 적용): ${name}`);
    continue;
  }
  await query(readFileSync(new URL(name, MIGRATIONS_DIR), 'utf8'));
  await query(`insert into public.drivelog_migrations (name) values ('${name.replaceAll("'", "''")}')`);
  console.log(`적용: ${name}`);
}

// 2. 차량 앱은 비밀번호 없이 익명 로그인으로 기기 계정을 만든다
await management('/config/auth', { method: 'PATCH', body: { external_anonymous_users_enabled: true } });
console.log('익명 로그인 켬');
console.log('완료. 다음: node backend/seed/seed.mjs');

// 시연용 데모 조직, 관리자 계정, 연결 코드를 만든다. 여러 번 실행해도 같은 결과가 된다.
// 데모 데이터는 이 스크립트에만 있고 APK에는 넣지 않는다.
// 사용: node backend/seed/seed.mjs
import { loadEnv } from '../scripts/env.mjs';

const env = loadEnv([
  'SUPABASE_URL', 'SUPABASE_SERVICE_ROLE_KEY',
  'DEMO_ORG_NAME', 'DEMO_ADMIN_EMAIL', 'DEMO_ADMIN_PASSWORD', 'DEMO_PAIRING_CODE',
]);
if (!/^[0-9]{6}$/.test(env.DEMO_PAIRING_CODE)) throw new Error('DEMO_PAIRING_CODE 는 6자리 숫자여야 합니다.');

const DEMO_CODE_EXPIRES_AT = '2027-02-28T23:59:59+09:00';

async function api(path, { method = 'GET', body, prefer } = {}) {
  const response = await fetch(env.SUPABASE_URL + path, {
    method,
    headers: {
      apikey: env.SUPABASE_SERVICE_ROLE_KEY,
      Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE_KEY}`,
      'Content-Type': 'application/json',
      ...(prefer && { Prefer: prefer }),
    },
    body: body && JSON.stringify(body),
  });
  const text = await response.text();
  if (!response.ok) throw new Error(`${method} ${path} → ${response.status} ${text}`);
  return text ? JSON.parse(text) : null;
}

// 1. 관리자 계정. 이메일 확인 처리해서 만들므로 실제 메일은 발송되지 않는다
async function ensureAdmin() {
  const { users } = await api('/auth/v1/admin/users?per_page=1000');
  const existing = users.find((user) => user.email === env.DEMO_ADMIN_EMAIL);
  if (existing) {
    await api(`/auth/v1/admin/users/${existing.id}`, { method: 'PUT', body: { password: env.DEMO_ADMIN_PASSWORD } });
    return existing;
  }
  return api('/auth/v1/admin/users', {
    method: 'POST',
    body: { email: env.DEMO_ADMIN_EMAIL, password: env.DEMO_ADMIN_PASSWORD, email_confirm: true },
  });
}

// 2. 데모 조직 (이름으로 찾고 없으면 만든다)
async function ensureOrg() {
  const [existing] = await api(`/rest/v1/organizations?name=eq.${encodeURIComponent(env.DEMO_ORG_NAME)}&select=*`);
  if (existing) return existing;
  const [created] = await api('/rest/v1/organizations', {
    method: 'POST', body: { name: env.DEMO_ORG_NAME }, prefer: 'return=representation',
  });
  return created;
}

