package com.altrostudio.drivelog.data.sync

import com.altrostudio.drivelog.data.remote.BackendApi
import com.altrostudio.drivelog.data.remote.BackendException
import com.altrostudio.drivelog.data.remote.DeviceSession
import com.altrostudio.drivelog.data.remote.PairRequest
import com.altrostudio.drivelog.data.remote.PairResponse
import com.altrostudio.drivelog.data.remote.RemoteChainHead
import com.altrostudio.drivelog.data.remote.RemoteTrip
import com.altrostudio.drivelog.data.remote.RemoteTripChange

/** 서버를 흉내 낸다. 올라온 기록은 id로 덮어써서 실제 서버(upsert)처럼 중복이 생기지 않는다 */
class FakeBackendApi : BackendApi {

    val trips = mutableMapOf<String, RemoteTrip>()
    val changes = mutableMapOf<String, RemoteTripChange>()
    val chainHeads = mutableMapOf<String, RemoteChainHead>()
    val usedTokens = mutableListOf<String>()
    var lastPairRequest: PairRequest? = null
    var pairResponse = PairResponse(
        status = "OK", orgId = "org-1", orgName = "데모 조직", vehicleId = "VIN-TEST", driverId = "driver-1", driverName = "기본 운전자"
    )

    /** 다음 호출부터 이 오류를 던진다 */
    var failure: BackendException? = null

    /** 다음 한 번은 토큰 만료(401)로 거부한다 */
    var rejectTokenOnce = false

    private var sessionCount = 0

    override suspend fun signInAnonymously() = newSession("refresh-1")

    override suspend fun refresh(refreshToken: String) = newSession(refreshToken)

    override suspend fun pairVehicle(accessToken: String, request: PairRequest): PairResponse {
        accept(accessToken)
        lastPairRequest = request
        return pairResponse
    }

    override suspend fun upsertTrips(accessToken: String, trips: List<RemoteTrip>) {
        accept(accessToken)
        trips.forEach { this.trips[it.id] = it }
    }

    override suspend fun upsertChanges(accessToken: String, changes: List<RemoteTripChange>) {
        accept(accessToken)
        changes.forEach { this.changes[it.id] = it }
    }

    override suspend fun upsertChainHead(accessToken: String, head: RemoteChainHead) {
        accept(accessToken)
        chainHeads[head.vehicleId] = head
    }

    private fun newSession(refreshToken: String) =
        DeviceSession("access-${++sessionCount}", refreshToken, expiresAtMs = Long.MAX_VALUE, userId = "device-user")

    private fun accept(token: String) {
        failure?.let { throw it }
        if (rejectTokenOnce) {
            rejectTokenOnce = false
            throw BackendException(BackendException.Kind.UNAUTHORIZED, "JWT expired")
        }
        usedTokens += token
    }
}

class MemorySyncSettings(override var vin: String? = null) : SyncSettings {
    override var deviceSession: DeviceSession? = null
    override var pairing: Pairing? = null
    override var pairingSkipped: Boolean = false
}

package com.altrostudio.drivelog.data.sync

import com.altrostudio.drivelog.data.remote.BackendException
import com.altrostudio.drivelog.data.remote.DeviceAuth
import com.altrostudio.drivelog.data.trip.SyncState
import com.altrostudio.drivelog.data.trip.TripPurpose
import com.altrostudio.drivelog.fake.FakeTripRepository
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.test.runTest
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

class SyncRepositoryTest {

    private var clock = 0L
    private val api = FakeBackendApi()
    private val pairing = MutableStateFlow<Pairing?>(null)
    private val trips = FakeTripRepository(now = { ++clock })
    private val sync = SyncRepository(api, DeviceAuth(api, MemorySyncSettings(), now = { 0L }), pairing, trips)

    private val demoOrg = Pairing(orgId = "org-1", orgName = "데모 조직", driverId = "driver-1", driverName = "기본 운전자")

    private suspend fun completedTrip(id: String, purpose: TripPurpose? = null) {
        trips.startTrip(id, VEHICLE_ID, at = 1_000, odometerKm = 100.0)
        trips.updateStart(id, socPercent = 80, address = "서울 강남구")
        trips.markParked(id, at = 2_000, odometerKm = 112.3)
        trips.updateEnd(id, socPercent = 75, address = "경기 성남시", efficiency = null)
        trips.completeTrip(id, at = 2_000)
        purpose?.let { trips.classify(id, it, "driver:default", at = 3_000) }
    }

    @Test
    fun `조직에 연결하기 전에는 아무것도 올리지 않는다`() = runTest {
        completedTrip("t1")
        assertEquals(SyncOutcome.NotPaired, sync.sync())
        assertTrue(api.trips.isEmpty())
    }

    @Test
    fun `연결되면 완료 운행과 분류 이력을 조직·운전자를 채워 올리고 올린 것으로 표시한다`() = runTest {
        completedTrip("t1", TripPurpose.BUSINESS)
        pairing.value = demoOrg

        assertEquals(SyncOutcome.Uploaded(trips = 1, changes = 1), sync.sync())

        val remote = api.trips.getValue("t1")
        assertEquals("org-1", remote.orgId)
        assertEquals("driver-1", remote.driverId)
        assertEquals("BUSINESS", remote.purpose)
        assertEquals(112.3, remote.endOdometerKm!!, 0.001)
        assertEquals(1L, remote.chainSeq)
        assertEquals(1, api.changes.size)
        assertEquals(2L, api.chainHeads.getValue(VEHICLE_ID).seq)
        assertEquals(SyncState.SYNCED, trips.trip("t1").syncState)
        assertEquals("org-1", trips.trip("t1").orgId)
        assertEquals(SyncOutcome.UpToDate, sync.sync())
    }

    @Test
    fun `진행 중인 운행은 올리지 않는다`() = runTest {
        trips.startTrip("t1", VEHICLE_ID, at = 1_000, odometerKm = 100.0)
        pairing.value = demoOrg
        assertEquals(SyncOutcome.UpToDate, sync.sync())
        assertTrue(api.trips.isEmpty())
    }

    @Test
    fun `인터넷이 없으면 기록을 그대로 두고 다음에 다시 올린다`() = runTest {
        completedTrip("t1")
        pairing.value = demoOrg
        api.failure = BackendException(BackendException.Kind.NETWORK, "offline")

        assertEquals(SyncOutcome.Offline, sync.sync())
        assertEquals(SyncState.PENDING, trips.trip("t1").syncState)

        api.failure = null
        assertEquals(SyncOutcome.Uploaded(trips = 1, changes = 0), sync.sync())
    }

    @Test
    fun `토큰이 거부되면 새 토큰을 받아 한 번 더 시도한다`() = runTest {
        completedTrip("t1")
        pairing.value = demoOrg
        api.rejectTokenOnce = true

        assertEquals(SyncOutcome.Uploaded(trips = 1, changes = 0), sync.sync())
        assertEquals("access-2", api.usedTokens.first())
    }

    @Test
    fun `올린 뒤 비업무로 다시 분류하면 주소를 지운 상태로 다시 올라간다`() = runTest {
        completedTrip("t1")
        pairing.value = demoOrg
        sync.sync()
        assertEquals("서울 강남구", api.trips.getValue("t1").startAddress)

        trips.classify("t1", TripPurpose.PERSONAL, "driver:default", at = 4_000)
        assertEquals(SyncOutcome.Uploaded(trips = 1, changes = 1), sync.sync())

        val remote = api.trips.getValue("t1")
        assertEquals("PERSONAL", remote.purpose)
        assertNull(remote.startAddress)
        assertNull(remote.endAddress)
        assertEquals(1, api.trips.size)
    }

    private companion object {
        const val VEHICLE_ID = "VIN-TEST"
    }
}

package com.altrostudio.drivelog.data.sync

import com.altrostudio.drivelog.data.remote.BackendException
import com.altrostudio.drivelog.data.remote.DeviceAuth
import com.altrostudio.drivelog.data.remote.PairResponse
import com.altrostudio.drivelog.fake.FakeTripRepository
import kotlinx.coroutines.test.runTest
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Test

class PairingRepositoryTest {

    private val api = FakeBackendApi()
    private val settings = MemorySyncSettings(vin = null).apply { pairingSkipped = true }
    private val trips = FakeTripRepository(now = { 0L })
    private val repository = PairingRepository(
        api, DeviceAuth(api, settings, now = { 0L }), settings, vehicleId = { "device-1234" }, trips, isConfigured = true
    )

    @Test
    fun `코드가 맞으면 조직에 연결되고 연결 전에 쌓인 운행에도 조직이 채워진다`() = runTest {
        trips.startTrip("t1", "device-1234", at = 1_000, odometerKm = 10.0)

        val result = repository.pair("123456")

        val expected = Pairing(orgId = "org-1", orgName = "데모 조직", driverId = "driver-1", driverName = "기본 운전자")
        assertEquals(PairingResult.Connected(expected), result)
        assertEquals(expected, settings.pairing)
        assertEquals(expected, repository.pairing.value)
        assertFalse(repository.skipped.value)
        assertEquals("org-1", trips.trip("t1").orgId)
        assertEquals("123456", api.lastPairRequest?.code)
        assertEquals("device-1234", api.lastPairRequest?.vehicleId)
        assertEquals("device-user", settings.deviceSession?.userId)
    }

    @Test
    fun `틀리거나 만료된 코드는 연결하지 않는다`() = runTest {
        api.pairResponse = PairResponse(status = "INVALID_CODE")
        assertEquals(PairingResult.InvalidCode, repository.pair("000000"))

        api.pairResponse = PairResponse(status = "EXPIRED_CODE")
        assertEquals(PairingResult.ExpiredCode, repository.pair("111111"))

        assertNull(settings.pairing)
        assertNull(repository.pairing.value)
    }

    @Test
    fun `인터넷이 없으면 오프라인으로 알린다`() = runTest {
        api.failure = BackendException(BackendException.Kind.NETWORK, "offline")
        assertEquals(PairingResult.Offline, repository.pair("123456"))
    }
}

