package com.altrostudio.drivelog.data.remote

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlinx.serialization.decodeFromString
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.RequestBody.Companion.toRequestBody
import java.io.IOException
import java.util.concurrent.TimeUnit

/**
 * Supabase REST API(GoTrue 인증, PostgREST)를 직접 호출한다. GMS가 없는 차량에서도 HTTPS만으로 동작한다.
 * 요청에는 공개(anon) 키와 차량 계정 토큰만 쓴다.
 */
class OkHttpBackendApi(
    private val config: SupabaseConfig,
    private val client: OkHttpClient = OkHttpClient.Builder().callTimeout(CALL_TIMEOUT_SECONDS, TimeUnit.SECONDS).build(),
    private val now: () -> Long = System::currentTimeMillis
) : BackendApi {

    private val json = Json { ignoreUnknownKeys = true }

    override suspend fun signInAnonymously(): DeviceSession =
        json.decodeFromString<AuthResponse>(post("/auth/v1/signup", "{}", token = null)).toSession()

    override suspend fun refresh(refreshToken: String): DeviceSession =
        json.decodeFromString<AuthResponse>(
            post("/auth/v1/token?grant_type=refresh_token", json.encodeToString(RefreshRequest(refreshToken)), token = null)
        ).toSession()

    override suspend fun pairVehicle(accessToken: String, request: PairRequest): PairResponse =
        json.decodeFromString(post("/rest/v1/rpc/pair_vehicle", json.encodeToString(request), accessToken))

    override suspend fun upsertTrips(accessToken: String, trips: List<RemoteTrip>) {
        post("/rest/v1/trips?on_conflict=id", json.encodeToString(trips), accessToken, prefer = UPSERT)
    }

    override suspend fun upsertChanges(accessToken: String, changes: List<RemoteTripChange>) {
        post("/rest/v1/trip_changes?on_conflict=id", json.encodeToString(changes), accessToken, prefer = UPSERT)
    }

    override suspend fun upsertChainHead(accessToken: String, head: RemoteChainHead) {
        post("/rest/v1/chain_heads?on_conflict=vehicle_id", json.encodeToString(listOf(head)), accessToken, prefer = UPSERT)
    }

    private fun AuthResponse.toSession() =
        DeviceSession(accessToken, refreshToken, now() + expiresInSeconds * 1_000, user.id)

    private suspend fun post(path: String, body: String, token: String?, prefer: String? = null): String =
        withContext(Dispatchers.IO) {
            if (!config.isConfigured) throw BackendException(BackendException.Kind.NOT_CONFIGURED, "서버 설정이 없는 빌드입니다")
            val request = Request.Builder()
                .url(config.url.trimEnd('/') + path)
                .post(body.toRequestBody(JSON_MEDIA_TYPE))
                .header("apikey", config.anonKey)
                .header("Authorization", "Bearer ${token ?: config.anonKey}")
                .apply { if (prefer != null) header("Prefer", prefer) }
                .build()
            try {
                client.newCall(request).execute().use { response ->
                    val text = response.body?.string().orEmpty()
                    when {
                        response.isSuccessful -> text
                        response.code == 401 -> throw BackendException(BackendException.Kind.UNAUTHORIZED, text)
                        else -> throw BackendException(BackendException.Kind.SERVER, "HTTP ${response.code}: $text")
                    }
                }
            } catch (e: IOException) {
                throw BackendException(BackendException.Kind.NETWORK, e.message ?: "네트워크 오류", e)
            }
        }

    private companion object {
        const val CALL_TIMEOUT_SECONDS = 20L
        const val UPSERT = "resolution=merge-duplicates,return=minimal"
        val JSON_MEDIA_TYPE = "application/json; charset=utf-8".toMediaType()
    }
}

package com.altrostudio.drivelog.data.remote

import kotlinx.coroutines.test.runTest
import okhttp3.mockwebserver.MockResponse
import okhttp3.mockwebserver.MockWebServer
import org.junit.After
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Before
import org.junit.Test

/** 실제 HTTP 요청 형식(경로, 헤더, JSON)이 Supabase REST API에 맞는지 가짜 웹서버로 확인한다 */
class OkHttpBackendApiTest {

    private val server = MockWebServer()

    @Before
    fun setUp() = server.start()

    @After
    fun tearDown() = server.shutdown()

    private fun api(config: SupabaseConfig = SupabaseConfig(server.url("/").toString(), "anon-key")) =
        OkHttpBackendApi(config, now = { 1_000L })

    private suspend fun failureKind(block: suspend () -> Unit): BackendException.Kind? = try {
        block()
        null
    } catch (e: BackendException) {
        e.kind
    }

    @Test
    fun `익명 로그인은 공개 키로 signup을 부르고 만료 시각을 계산한다`() = runTest {
        server.enqueue(
            MockResponse().setBody("""{"access_token":"a","refresh_token":"r","expires_in":3600,"token_type":"bearer","user":{"id":"u1","is_anonymous":true}}""")
        )

        val session = api().signInAnonymously()

        assertEquals(DeviceSession("a", "r", 1_000L + 3_600_000L, "u1"), session)
        val request = server.takeRequest()
        assertEquals("POST", request.method)
        assertEquals("/auth/v1/signup", request.path)
        assertEquals("anon-key", request.getHeader("apikey"))
        assertEquals("Bearer anon-key", request.getHeader("Authorization"))
    }

    @Test
    fun `연결 요청은 차량 토큰으로 pair_vehicle 함수를 부른다`() = runTest {
        server.enqueue(MockResponse().setBody("""{"status":"OK","org_id":"o1","org_name":"데모","vehicle_id":"v1","driver_id":"d1","driver_name":"기본 운전자"}"""))

        val response = api().pairVehicle("device-token", PairRequest("123456", "v1", null))

        assertEquals("데모", response.orgName)
        val request = server.takeRequest()
        assertEquals("/rest/v1/rpc/pair_vehicle", request.path)
        assertEquals("Bearer device-token", request.getHeader("Authorization"))
        assertEquals("""{"p_code":"123456","p_vehicle_id":"v1","p_vin":null}""", request.body.readUtf8())
    }

    @Test
    fun `운행은 id 기준으로 덮어쓰고 빈 값도 null로 보내 서버 값을 지운다`() = runTest {
        server.enqueue(MockResponse().setResponseCode(201))
        val trip = RemoteTrip(
            id = "t1", orgId = "o1", vehicleId = "v1", driverId = null, startedAtMs = 1, endedAtMs = 2,
            startOdometerKm = 100.0, endOdometerKm = 112.3, odometerSource = "VEHICLE", startSocPercent = null,
            endSocPercent = null, efficiency = null, efficiencyType = null, startAddress = null, endAddress = null,
            visitNote = null, purpose = "PERSONAL", chainSeq = 1, prevHash = "0".repeat(64), hash = "a".repeat(64)
        )

        api().upsertTrips("device-token", listOf(trip))

        val request = server.takeRequest()
        assertEquals("/rest/v1/trips?on_conflict=id", request.path)
        assertEquals("resolution=merge-duplicates,return=minimal", request.getHeader("Prefer"))
        val body = request.body.readUtf8()
        assertTrue(body.startsWith("["))
        assertTrue(body.contains("\"start_address\":null"))
        assertTrue(body.contains("\"end_odometer_km\":112.3"))
        assertTrue(body.contains("\"chain_seq\":1"))
    }

    @Test
    fun `토큰이 거부되면 UNAUTHORIZED, 서버 오류면 SERVER`() = runTest {
        server.enqueue(MockResponse().setResponseCode(401).setBody("""{"message":"JWT expired"}"""))
        server.enqueue(MockResponse().setResponseCode(500))

        assertEquals(BackendException.Kind.UNAUTHORIZED, failureKind { api().upsertChainHead("t", RemoteChainHead("v1", "o1", 1, "h")) })
        assertEquals(BackendException.Kind.SERVER, failureKind { api().upsertChainHead("t", RemoteChainHead("v1", "o1", 1, "h")) })
    }

    @Test
    fun `서버에 닿지 않으면 NETWORK, 설정이 없으면 NOT_CONFIGURED`() = runTest {
        val unreachable = SupabaseConfig("http://127.0.0.1:1", "anon-key")
        assertEquals(BackendException.Kind.NETWORK, failureKind { api(unreachable).signInAnonymously() })
        assertEquals(BackendException.Kind.NOT_CONFIGURED, failureKind { api(SupabaseConfig("", "")).signInAnonymously() })
    }
}

